    private val exact = entries.filterNot { "{{VAR" in it.source }.associateBy { it.source }
    private val templates = entries.filter { "{{VAR" in it.source }.sortedByDescending { it.source.length }
    private val variablePattern = Regex("\\{\\{VAR(\\d+)}}")

    fun translate(text: String, language: AppLanguage): String {
        if (language == AppLanguage.English) exact[text]?.let { return polish(it.english, language) }
        if (language == AppLanguage.Indonesian) exact[text]?.let { return polish(it.indonesian, language) }
        for (entry in templates) {
            val captures = matchTemplate(entry.source, text) ?: continue
            val translated = if (language == AppLanguage.English) entry.english else entry.indonesian
            return polish(
                variablePattern.replace(translated) {
                    captures.getOrNull(it.groupValues[1].toInt()) ?: it.value
                },
                language,
            )
        }
        return text
    }

    private fun polish(text: String, language: AppLanguage): String =
        when (language) {
            AppLanguage.English -> text
                .replace("creative workshop", "Steam Workshop", ignoreCase = true)
                .replace("scientific internet", "a proxy or VPN", ignoreCase = true)
                .replace("module", "mod", ignoreCase = true)
            AppLanguage.Indonesian -> text
                .replace("bengkel kreatif", "Steam Workshop", ignoreCase = true)
                .replace("lokakarya", "Steam Workshop", ignoreCase = true)
                .replace("uap", "Steam", ignoreCase = true)
                .replace("modul", "mod", ignoreCase = true)
                .replace("perpustakaan mod", "Pustaka Mod", ignoreCase = true)
                .replace("unduh kemajuan", "Progres unduhan", ignoreCase = true)
                .replace("panggung", "tahap", ignoreCase = true)
                .replace("internet ilmiah", "proxy atau VPN", ignoreCase = true)

    private fun matchTemplate(template: String, text: String): List<String>? {
        val matches = variablePattern.findAll(template).toList()
        if (matches.isEmpty()) return null
        val captures = mutableListOf<String>()
        var templateCursor = 0
        var textCursor = 0
        matches.forEachIndexed { index, match ->
            val prefix = template.substring(templateCursor, match.range.first)
            if (!text.startsWith(prefix, textCursor)) return null
            textCursor += prefix.length
            templateCursor = match.range.last + 1
            val suffixEnd = matches.getOrNull(index + 1)?.range?.first ?: template.length
            val suffix = template.substring(templateCursor, suffixEnd)
            val captureEnd = if (suffix.isEmpty()) text.length else text.indexOf(suffix, textCursor)
            if (captureEnd < textCursor) return null
            captures += text.substring(textCursor, captureEnd)
            textCursor = captureEnd
        }
        if (!text.startsWith(template.substring(templateCursor), textCursor)) return null
        if (textCursor + template.substring(templateCursor).length != text.length) return null
        return captures
    }
}
